insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O confisco dos instrumentos e produtos do crime, no caso previsto no art. 100 do Código Penal, será decretado no despacho de arquivamento do inquérito, na sentença de impronúncia ou na sentença absolutória.', '["Confisco de instrumentos e produtos do crime decretado no arquivamento, na impronúncia ou na absolvição."]'::jsonb, '["Confisco independe de condenação nesses casos."]'::jsonb, 'Na sentença absolutória, o juiz decreta o confisco do instrumento ilícito.', '["Assertiva que condiciona o confisco do art. 779 à condenação erra."]'::jsonb, '[]'::jsonb, '["Art. 119","Art. 124"]'::jsonb, 'under_review', 'claude'
