insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Sem prejuízo de convenções ou tratados, aplicar-se-á o disposto neste Título à homologação de sentenças penais estrangeiras e à expedição e ao cumprimento de cartas rogatórias para citações, inquirições e outras diligências necessárias à instrução de processo penal.', '["O Título rege a homologação de sentenças penais estrangeiras.","Rege também as cartas rogatórias, sem prejuízo de tratados."]'::jsonb, '["Tratados e convenções prevalecem."]'::jsonb, 'A carta rogatória para ouvir testemunha no exterior segue este Título, salvo tratado.', '["Assertiva que afasta os tratados internacionais em favor do CPP erra."]'::jsonb, '[]'::jsonb, '["Art. 783"]'::jsonb, 'under_review', 'claude'
