insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'As sentenças estrangeiras não serão homologadas, nem as cartas rogatórias cumpridas, se contrárias à ordem pública e aos bons costumes.', '["Sentenças estrangeiras e cartas rogatórias contrárias à ordem pública e aos bons costumes não são homologadas ou cumpridas."]'::jsonb, '["Limite da ordem pública."]'::jsonb, 'Uma carta rogatória contrária à ordem pública brasileira não é cumprida.', '["Assertiva que obriga o cumprimento de carta rogatória contrária à ordem pública erra."]'::jsonb, '[]'::jsonb, '["Art. 780"]'::jsonb, 'under_review', 'claude'
