insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O trânsito, por via diplomática, dos documentos apresentados constituirá prova bastante de sua autenticidade.', '["Documentos transmitidos por via diplomática têm autenticidade comprovada."]'::jsonb, '["Via diplomática comprova a autenticidade."]'::jsonb, 'O documento enviado por via diplomática dispensa outra prova de autenticidade.', '["Assertiva que exige nova autenticação de documento que tramitou por via diplomática erra."]'::jsonb, '[]'::jsonb, '["Art. 783"]'::jsonb, 'under_review', 'claude'
