insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'As cartas rogatórias serão, pelo respectivo juiz, remetidas ao Ministro da Justiça, a fim de ser pedido o seu cumprimento, por via diplomática, às autoridades estrangeiras competentes.', '["Cartas rogatórias remetidas pelo juiz ao Ministro da Justiça.","Cumprimento pedido por via diplomática."]'::jsonb, '["Trâmite por via diplomática."]'::jsonb, 'O juiz remete ao Ministro da Justiça a carta rogatória para ouvir testemunha no exterior.', '["Assertiva que permite ao juiz enviar a carta rogatória diretamente à autoridade estrangeira erra."]'::jsonb, '[]'::jsonb, '["Art. 780"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-783'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'As cartas rogatórias emanadas de autoridades estrangeiras competentes não dependem de homologação e serão atendidas se encaminhadas por via diplomática e desde que o crime, segundo a lei brasileira, não exclua a extradição. As rogatórias, acompanhadas de tradução, serão, após exequatur do presidente do Supremo Tribunal Federal, cumpridas pelo juiz criminal do lugar onde as diligências tenham de efetuar-se. A carta rogatória será remetida pelo presidente do STF ao presidente do Tribunal de Apelação do Estado, do Distrito Federal ou do Território. Versando sobre crime de ação privada, o andamento depende do interessado, a quem incumbirá o pagamento das despesas. Ficará sempre na secretaria do STF cópia da carta rogatória.', '["Rogatória estrangeira dispensa homologação, mas exige via diplomática e crime que não exclua a extradição.","Tradução e exequatur do presidente do STF.","Cumprimento pelo juiz criminal do lugar.","Crime de ação privada: andamento e despesas pelo interessado.","Cópia fica no STF."]'::jsonb, '["Hoje o exequatur é do Superior Tribunal de Justiça (Emenda Constitucional 45)."]'::jsonb, 'A rogatória estrangeira vem por via diplomática e recebe exequatur antes de ser cumprida.', '["Assertiva que exige homologação das rogatórias estrangeiras erra: elas dependem de exequatur, e não de homologação."]'::jsonb, '[{"termo":"Exequatur","significado":"Autorização para cumprir no Brasil ato de autoridade estrangeira."}]'::jsonb, '["Art. 783"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-784'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Concluídas as diligências, a carta rogatória será devolvida ao presidente do Supremo Tribunal Federal, por intermédio do presidente do Tribunal de Apelação, o qual, antes de devolvê-la, mandará completar qualquer diligência ou sanar qualquer nulidade.', '["Rogatória cumprida volta ao presidente do STF, por intermédio do presidente do Tribunal de Apelação.","O presidente completa diligências ou sana nulidades antes de devolver."]'::jsonb, '["Devolução com saneamento."]'::jsonb, 'Antes de devolver a rogatória, o presidente do tribunal manda completar uma diligência.', '["Assertiva que dispensa o saneamento de nulidades antes da devolução erra."]'::jsonb, '[]'::jsonb, '["Art. 784"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-785'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O despacho que conceder o exequatur marcará, para o cumprimento da diligência, prazo razoável, que poderá ser excedido, havendo justa causa, ficando esta consignada em ofício dirigido ao presidente do Supremo Tribunal Federal, juntamente com a carta rogatória.', '["Exequatur fixa prazo razoável para o cumprimento.","Pode ser excedido por justa causa, consignada em ofício ao presidente do STF."]'::jsonb, '["Justa causa registrada em ofício."]'::jsonb, 'O prazo da diligência é excedido, e a justa causa é informada em ofício.', '["Assertiva que veda qualquer excesso do prazo fixado no exequatur erra."]'::jsonb, '[]'::jsonb, '["Art. 784"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-786'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'As sentenças estrangeiras deverão ser previamente homologadas pelo Supremo Tribunal Federal para que produzam os efeitos do art. 7º do Código Penal. Hoje a competência é do Superior Tribunal de Justiça.', '["Sentença estrangeira precisa de homologação prévia para produzir os efeitos do art. 7º do CP.","A competência passou ao STJ."]'::jsonb, '["Homologação é do STJ após a Emenda Constitucional 45."]'::jsonb, 'A sentença penal estrangeira só produz efeitos no Brasil depois de homologada.', '["Assertiva que dispensa a homologação da sentença estrangeira para produzir efeitos erra."]'::jsonb, '[]'::jsonb, '["Art. 788"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-787'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A sentença penal estrangeira será homologada, quando a aplicação da lei brasileira produzir na espécie as mesmas consequências e concorrerem os seguintes requisitos: estar revestida das formalidades externas necessárias, segundo a legislação do país de origem; haver sido proferida por juiz competente, mediante citação regular, segundo a mesma legislação; ter passado em julgado; estar devidamente autenticada por cônsul brasileiro; e estar acompanhada de tradução feita por tradutor público.', '["Mesmas consequências pela lei brasileira.","Formalidades externas segundo a lei do país de origem.","Juiz competente e citação regular.","Trânsito em julgado.","Autenticação por cônsul brasileiro e tradução por tradutor público."]'::jsonb, '["Cinco requisitos, além da equivalência de consequências."]'::jsonb, 'A sentença estrangeira transitada em julgado, autenticada e traduzida pode ser homologada.', '["Assertiva que dispensa o trânsito em julgado da sentença estrangeira erra."]'::jsonb, '[]'::jsonb, '["Art. 787"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-788'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O procurador-geral da República, sempre que tiver conhecimento da existência de sentença penal estrangeira, emanada de Estado que tenha com o Brasil tratado de extradição e que haja imposto medida de segurança pessoal ou pena acessória que deva ser cumprida no Brasil, pedirá ao Ministro da Justiça providências para a homologação. A homologação de sentença de Estado que não tiver tratado de extradição dependerá de requisição do Ministro da Justiça. Distribuído o requerimento, o relator mandará citar o interessado para deduzir embargos, dentro de dez dias se residir no Distrito Federal, de trinta dias no caso contrário. Se o interessado não deduzir embargos, será nomeado defensor, que produzirá a defesa em dez dias. Os embargos somente poderão fundar-se em dúvida sobre a autenticidade do documento, sobre a inteligência da sentença ou sobre a falta de requisito dos arts. 781 e 788.', '["PGR provoca a homologação de sentença de Estado com tratado de extradição.","Sem tratado: requisição do Ministro da Justiça.","Embargos em dez dias (Distrito Federal) ou trinta dias (demais).","Sem embargos: defensor nomeado, com dez dias.","Embargos só por dúvida sobre autenticidade, inteligência da sentença ou falta de requisito."]'::jsonb, '["Prazos de embargos: 10 e 30 dias."]'::jsonb, 'O interessado que reside fora do Distrito Federal tem trinta dias para embargar.', '["Assertiva que fixa em dez dias o prazo de embargos para quem reside fora do Distrito Federal erra: são trinta."]'::jsonb, '[]'::jsonb, '["Art. 787","Art. 788"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-789'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O interessado na execução de sentença penal estrangeira, para a reparação do dano, restituição e outros efeitos civis, poderá requerer ao Supremo Tribunal Federal a sua homologação, observando-se o que a respeito prescreve o Código de Processo Civil.', '["Interessado na reparação do dano e efeitos civis pode requerer a homologação.","Segue o Código de Processo Civil."]'::jsonb, '["Hoje a competência é do STJ."]'::jsonb, 'A vítima busca homologar a sentença estrangeira para executar a reparação do dano.', '["Assertiva que restringe a homologação aos efeitos penais erra: abrange efeitos civis."]'::jsonb, '[]'::jsonb, '["Art. 787"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-790'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Em todos os juízos e tribunais do crime, além das audiências e sessões ordinárias, haverá as extraordinárias, de acordo com as necessidades do rápido andamento dos feitos.', '["Além das ordinárias, haverá audiências e sessões extraordinárias, conforme a necessidade."]'::jsonb, '["Celeridade processual."]'::jsonb, 'O juízo marca audiência extraordinária para acelerar um processo com réu preso.', '["Assertiva que proíbe audiências extraordinárias erra."]'::jsonb, '[]'::jsonb, '["Art. 792"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-791'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'As audiências, sessões e atos processuais serão, em regra, públicos e se realizarão nas sedes dos juízos e tribunais, com assistência dos escrivães, do secretário e do oficial de justiça que servir de porteiro, em dia e hora certos. Se da publicidade puder resultar escândalo, inconveniente grave ou perigo de perturbação da ordem, o juiz ou tribunal poderá, de ofício ou a requerimento, determinar que o ato seja realizado a portas fechadas. Em caso de necessidade, poderão realizar-se na residência do juiz, ou em outra casa por ele designada.', '["Regra: publicidade.","Realizam-se nas sedes dos juízos e tribunais, em dia e hora certos.","Escândalo, inconveniente grave ou perigo de perturbação: portas fechadas.","Necessidade: na residência do juiz ou outra casa designada."]'::jsonb, '["Segredo de justiça só em hipóteses legais (Constituição, art. 93, IX)."]'::jsonb, 'Por risco de perturbação da ordem, o juiz determina audiência a portas fechadas.', '["Assertiva que torna o sigilo das audiências a regra erra: a regra é a publicidade."]'::jsonb, '[]'::jsonb, '["Art. 793"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-792'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Nas audiências e nas sessões, os advogados, as partes, os escrivães e os espectadores poderão estar sentados. Todos, porém, se levantarão quando se dirigirem aos juízes ou quando estes se levantarem para qualquer ato do processo. Nos atos da instrução criminal, perante os juízes singulares, os advogados poderão requerer sentados.', '["Todos podem permanecer sentados nas audiências.","Levantam-se ao se dirigir aos juízes ou quando eles se levantam.","Perante juiz singular, os advogados podem requerer sentados."]'::jsonb, '["Norma de etiqueta forense."]'::jsonb, 'O advogado requer sentado na instrução diante do juiz singular.', '["Assertiva que obriga os advogados a requerer sempre em pé erra: perante juiz singular podem requerer sentados."]'::jsonb, '[]'::jsonb, '["Art. 794"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-793'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A polícia das audiências e das sessões compete aos respectivos juízes ou ao presidente do tribunal, câmara ou turma, que poderão determinar o que for conveniente à manutenção da ordem. Para tal fim, requisitarão força pública, que ficará exclusivamente à sua disposição.', '["Juízes e presidentes mantêm a ordem nas audiências e sessões.","Podem requisitar força pública, sob sua exclusiva disposição."]'::jsonb, '["Poder de polícia das audiências."]'::jsonb, 'O presidente da sessão requisita a força pública para manter a ordem.', '["Assertiva que atribui a polícia das audiências à autoridade policial erra: compete ao juiz ou ao presidente."]'::jsonb, '[]'::jsonb, '["Art. 251"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-794'
