insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Os espectadores das audiências ou das sessões não poderão manifestar-se. O juiz ou o presidente fará retirar da sala os desobedientes, que, em caso de resistência, serão presos e autuados.', '["Espectadores não podem se manifestar.","Desobedientes são retirados da sala.","Resistência: prisão e autuação."]'::jsonb, '["Silêncio dos espectadores."]'::jsonb, 'Um espectador que grita é retirado da sala pelo juiz.', '["Assertiva que permite manifestação dos espectadores nas audiências erra."]'::jsonb, '[]'::jsonb, '["Art. 794"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-795'
