insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Os atos de instrução ou julgamento prosseguirão com a assistência do defensor, se o réu se portar inconvenientemente.', '["Réu que se porta inconvenientemente: o ato prossegue com o defensor."]'::jsonb, '["O defensor sempre acompanha o ato."]'::jsonb, 'O réu perturba a audiência, que continua com a presença do defensor.', '["Assertiva que suspende o ato por mau comportamento do réu, sem prosseguir com o defensor, erra."]'::jsonb, '[]'::jsonb, '["Art. 497, VI"]'::jsonb, 'under_review', 'claude'
