insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Excetuadas as sessões de julgamento, que não serão marcadas para domingo ou dia feriado, os demais atos do processo poderão ser praticados em período de férias, em domingos e dias feriados. Todavia, os julgamentos iniciados em dia útil não se interromperão pela superveniência de feriado ou domingo.', '["Sessões de julgamento não são marcadas em domingo ou feriado.","Demais atos podem ocorrer em férias, domingos e feriados.","Julgamento iniciado em dia útil não se interrompe por feriado ou domingo."]'::jsonb, '["Exceção só às sessões de julgamento."]'::jsonb, 'Um ato de investigação é praticado em feriado; a sessão do Júri, não.', '["Assertiva que permite marcar sessão de julgamento para domingo erra."]'::jsonb, '[]'::jsonb, '["Art. 798"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-797'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Todos os prazos correrão em cartório e serão contínuos e peremptórios, não se interrompendo por férias, domingo ou dia feriado. Não se computará no prazo o dia do começo, incluindo-se, porém, o do vencimento. A terminação dos prazos será certificada nos autos pelo escrivão, mas será considerado findo o prazo ainda que omitida aquela formalidade. O prazo que terminar em domingo ou feriado considerar-se-á prorrogado até o dia útil imediato. Não correrão os prazos se houver impedimento do juiz, força maior ou obstáculo judicial oposto pela parte contrária. Salvo casos expressos, os prazos correrão da intimação, da audiência ou sessão em que for proferida a decisão, se presente a parte, ou do dia em que a parte manifestar nos autos ciência inequívoca da sentença ou despacho.', '["Prazos contínuos e peremptórios.","Exclui-se o dia do começo e inclui-se o do vencimento.","Prazo que termina em domingo ou feriado prorroga-se para o dia útil seguinte.","Não correm por impedimento do juiz, força maior ou obstáculo judicial da parte contrária.","Contagem: da intimação, da audiência (se presente) ou da ciência inequívoca."]'::jsonb, '["Prazos CONTÍNUOS (sem suspensão por feriados), mas prorrogados se o último dia não for útil."]'::jsonb, 'O prazo termina no sábado e passa para a segunda-feira seguinte.', '["Assertiva que conta o dia do começo do prazo erra: ele é excluído."]'::jsonb, '[]'::jsonb, '["Art. 798-A"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-798'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Suspende-se o curso do prazo processual nos dias compreendidos entre 20 de dezembro e 20 de janeiro, inclusive, salvo nos casos que envolvam réus presos, nos processos vinculados a essas prisões; nos procedimentos regidos pela Lei Maria da Penha; e nas medidas consideradas urgentes, mediante despacho fundamentado do juízo competente. Durante o período, fica vedada a realização de audiências e de sessões de julgamento, salvo nas hipóteses dos incisos I, II e III.', '["Prazos suspensos de 20 de dezembro a 20 de janeiro.","Exceções: réus presos, Lei Maria da Penha e medidas urgentes fundamentadas.","Vedadas audiências e sessões de julgamento no período, salvo as exceções."]'::jsonb, '["Incluído pela Lei nº 14.365, de 2022.","Período: 20 de dezembro a 20 de janeiro."]'::jsonb, 'Em processo de réu preso, os prazos continuam correndo em janeiro.', '["Assertiva que suspende também os prazos dos processos com réu preso erra: eles continuam a correr."]'::jsonb, '[]'::jsonb, '["Art. 798"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-798-a'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O escrivão, sob pena de multa e, na reincidência, suspensão até 30 dias, executará dentro do prazo de dois dias os atos determinados em lei ou ordenados pelo juiz.', '["Escrivão cumpre os atos em dois dias.","Sanção: multa e, na reincidência, suspensão de até 30 dias."]'::jsonb, '["Prazo de dois dias."]'::jsonb, 'O escrivão cumpre em dois dias a ordem do juiz, sob pena de multa.', '["Assertiva que fixa em cinco dias o prazo do escrivão para cumprir os atos erra: são dois dias."]'::jsonb, '[]'::jsonb, '["Art. 800"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-799'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Os juízes singulares darão seus despachos e decisões dentro dos seguintes prazos, quando outros não estiverem estabelecidos: de dez dias, se a decisão for definitiva ou interlocutória mista; de cinco dias, se for interlocutória simples; e de um dia, se se tratar de despacho de expediente. Os prazos para o juiz contam-se do termo de conclusão; os do Ministério Público, do termo de vista, salvo para recurso. Em qualquer instância, declarando motivo justo, poderá o juiz exceder por igual tempo os prazos. O escrivão que não enviar os autos no dia em que assinar termo de conclusão ou de vista sujeita-se à sanção do art. 799.', '["Decisão definitiva ou interlocutória mista: dez dias.","Interlocutória simples: cinco dias.","Despacho de expediente: um dia.","Prazos do juiz contam da conclusão; do MP, da vista.","Pode exceder por igual tempo, com motivo justo."]'::jsonb, '["Prazos impróprios para o juiz: dez, cinco e um dia."]'::jsonb, 'O juiz profere a sentença em dez dias do termo de conclusão.', '["Assertiva que fixa em cinco dias o prazo para decisão definitiva erra: são dez dias."]'::jsonb, '[]'::jsonb, '["Art. 799","Art. 801"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-800'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Findos os respectivos prazos, os juízes e os órgãos do Ministério Público, responsáveis pelo retardamento, perderão tantos dias de vencimentos quantos forem os excedidos. Na contagem do tempo de serviço, para efeito de promoção e aposentadoria, a perda será do dobro dos dias excedidos.', '["Juízes e membros do MP perdem tantos dias de vencimentos quantos excederem o prazo.","Tempo de serviço: perda do dobro dos dias excedidos."]'::jsonb, '["Dispositivo raramente aplicado."]'::jsonb, 'Texto de aplicação rara, sobre desconto de vencimentos por atraso.', '["Assertiva que isenta o MP da sanção por atraso nos prazos erra."]'::jsonb, '[]'::jsonb, '["Art. 802"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-801'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O desconto referido no artigo antecedente far-se-á à vista da certidão do escrivão do processo ou do secretário do tribunal, que deverão, de ofício ou a requerimento de qualquer interessado, remetê-la às repartições encarregadas do pagamento e da contagem do tempo de serviço.', '["Desconto feito à vista de certidão do escrivão ou secretário.","Remessa, de ofício ou a requerimento, às repartições de pagamento e de contagem do tempo."]'::jsonb, '["Procedimento do desconto do art. 801."]'::jsonb, 'O escrivão expede certidão do atraso para o desconto de vencimentos.', '["Assertiva que dispensa a certidão do escrivão para o desconto do art. 801 erra."]'::jsonb, '[]'::jsonb, '["Art. 801"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-802'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Salvo nos casos expressos em lei, é proibida a retirada de autos do cartório, ainda que em confiança, sob pena de responsabilidade do escrivão.', '["Proibida a retirada de autos do cartório, salvo casos legais.","Escrivão responde pelo descumprimento."]'::jsonb, '["Hoje vale o processo eletrônico e o direito do advogado à carga, na forma da lei."]'::jsonb, 'O escrivão não entrega os autos físicos a quem não tem direito legal à carga.', '["Assertiva que permite a retirada de autos do cartório em confiança, sem previsão legal, erra."]'::jsonb, '[]'::jsonb, '["Art. 801"]'::jsonb, 'under_review', 'claude'
