insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A sentença ou o acórdão que julgar a ação, qualquer incidente ou recurso, condenará nas custas o vencido.', '["O vencido é condenado nas custas."]'::jsonb, '["Princípio da sucumbência quanto às custas."]'::jsonb, 'O réu condenado paga as custas processuais.', '["Assertiva que isenta o vencido das custas, sempre, erra."]'::jsonb, '[]'::jsonb, '["Art. 805"]'::jsonb, 'under_review', 'claude'
