select u.id, u.content_sha256, 'As custas serão contadas e cobradas de acordo com os regulamentos expedidos pela União e pelos Estados.', '["Custas contadas e cobradas segundo regulamentos da União e dos Estados."]'::jsonb, '["Regulamentação fora do CPP."]'::jsonb, 'As custas seguem o regimento estadual de custas.', '["Assertiva que fixa as custas apenas pelo CPP erra: seguem os regulamentos da União e dos Estados."]'::jsonb, '[]'::jsonb, '["Art. 804"]'::jsonb, 'under_review', 'claude'
