insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Salvo o caso do art. 32, nas ações intentadas mediante queixa, nenhum ato ou diligência se realizará sem que seja depositada em cartório a importância das custas. Igualmente, nenhum ato requerido no interesse da defesa será realizado sem o prévio pagamento das custas, salvo se o acusado for pobre. A falta do pagamento das custas, nos prazos fixados em lei, ou marcados pelo juiz, importará renúncia à diligência requerida ou deserção do recurso interposto. A falta de qualquer prova ou diligência que deixe de realizar-se em virtude do não pagamento de custas não implicará a nulidade do processo, se a prova de pobreza do acusado só posteriormente foi feita.', '["Ação por queixa: custas depositadas antes dos atos, salvo ofendido pobre.","Defesa: pagamento prévio das custas, salvo acusado pobre.","Falta de pagamento: renúncia à diligência ou deserção do recurso.","Falta de prova por custas não anula o processo se a pobreza só foi provada depois."]'::jsonb, '["Pobreza dispensa o pagamento."]'::jsonb, 'O querelante não deposita as custas e o ato não é realizado.', '["Assertiva que exige o pagamento prévio de custas do acusado pobre erra."]'::jsonb, '[]'::jsonb, '["Art. 32"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-806'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O disposto no artigo anterior não obstará à faculdade atribuída ao juiz de determinar de ofício inquirição de testemunhas ou outras diligências.', '["A exigência de custas não impede o juiz de determinar, de ofício, testemunhas ou diligências."]'::jsonb, '["Iniciativa do juiz independe de custas."]'::jsonb, 'Mesmo sem custas pagas, o juiz determina de ofício a oitiva de uma testemunha.', '["Assertiva que condiciona as diligências de ofício do juiz ao pagamento de custas erra."]'::jsonb, '[]'::jsonb, '["Art. 806"]'::jsonb, 'under_review', 'claude'
