insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A estatística judiciária criminal, a cargo do Instituto de Identificação e Estatística ou repartições congêneres, terá por base o boletim individual, parte integrante dos processos, e versará sobre crimes e contravenções, armas apreendidas, número de delinquentes e seus dados pessoais, casos de codelinquência, reincidência e antecedentes, sentenças, natureza das penas e medidas de segurança, suspensão condicional da pena e concessões ou denegações de habeas corpus. Os dados constituem o mínimo exigível e serão lançados semestralmente em mapa.', '["Estatística criminal feita com base no boletim individual.","Abrange crimes, armas, delinquentes, reincidência, sentenças, penas, medidas de segurança, sursis e habeas corpus.","Dados mínimos, acrescidos de outros úteis.","Lançados semestralmente em mapa."]'::jsonb, '["Estatística semestral."]'::jsonb, 'O instituto compila semestralmente as estatísticas criminais a partir do boletim individual.', '["Assertiva que dispensa o boletim individual das estatísticas criminais erra."]'::jsonb, '[]'::jsonb, '["Art. 23"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-809'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Este Código entrará em vigor no dia 1º de janeiro de 1942, dispositivo hoje meramente histórico.', '["Cláusula de vigência do Código de Processo Penal original."]'::jsonb, '["Dispositivo histórico."]'::jsonb, 'O artigo apenas marca o início de vigência do Código.', '["Assertiva que atribui ao art. 810 efeito prático sobre os processos atuais erra."]'::jsonb, '[]'::jsonb, '["Art. 811"]'::jsonb, 'under_review', 'claude'
